36	// The people on the active sheet: one form to add a person or edit an existing one, the list with
37	// each person's claims and due-total, and the sheet's claimed-total and due-total.
38	@Component({
39	  selector: 'app-people',
40	  imports: [ReactiveFormsModule, SheetHeader, PersonClaims, PeriodsPanel, SummaryPanel],
41	  template: `
42	    <app-header [peopleCount]="people().length" [statuses]="summaryByStatus()" [dueTotal]="dueTotal()"
43	                [overdueTotal]="money(overdueTotals().cents)" />
44	    <app-periods [dueTotals]="dueByPeriod()" />
45	    <app-summary [grades]="summaryByGrade()" [periods]="summaryByPeriod()" [statuses]="summaryByStatus()" />
46	
47	    <section aria-labelledby="people-heading">
48	      <h2 id="people-heading">People</h2>
49	      <p>Claimed in total: <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
50	      <p>Due in total: <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
51	      <p>Overdue: <strong data-testid="rollup-overdue-count">{{ overdueTotals().count }}</strong>
52	        claims, due <strong data-testid="rollup-overdue-total">{{ money(overdueTotals().cents) }}</strong></p>
53	
54	      <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="editingId() === null ? 'Add a person' : 'Edit a person'">
55	        <label for="person-form-name">Name</label>
56	        <input id="person-form-name" data-testid="person-form-name" formControlName="name" autocomplete="off" />
57	        <label for="person-form-grade">Grade</label>
58	        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
59	          @for (g of grades; track g) {
60	            <option [value]="g">{{ g }}</option>
61	          }
62	        </select>
63	        @if (editingId() !== null) {
64	          <label for="person-form-grade-from">Grade from</label>
65	          <input id="person-form-grade-from" type="date" data-testid="person-form-grade-from" formControlName="gradeFrom" />
66	        }
67	        <button type="submit" data-testid="person-form-submit" [disabled]="saving()">
68	          {{ editingId() === null ? 'Add person' : 'Save person' }}
69	        </button>
70	        @if (editingId() !== null) {
71	          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
72	        }
73	        @if (error(); as err) {
74	          <p role="alert" data-testid="person-form-error">{{ err }}</p>
75	        }
76	      </form>
77	
78	      <form [formGroup]="quickForm" (ngSubmit)="quickAdd()" aria-label="Quick-add a claim">
79	        <label for="quick-name">Name</label>
80	        <input id="quick-name" data-testid="quick-name" formControlName="name" autocomplete="off" />
81	        <label for="quick-amount">Amount</label>
82	        <input id="quick-amount" data-testid="quick-amount" formControlName="amount" inputmode="decimal" autocomplete="off" />
83	        <button type="submit" data-testid="quick-submit" [disabled]="quickSaving()">Quick add</button>
84	        @if (quickError(); as err) {
85	          <p role="alert" data-testid="quick-error">{{ err }}</p>
86	        }
87	      </form>
88	
89	      <p>
90	        <input id="show-retired" type="checkbox" data-testid="show-retired"
91	               [checked]="api.showRetired()" (change)="api.showRetired.set($any($event.target).checked)" />
92	        <label for="show-retired">Show retired</label>
93	      </p>
94	
95	      <p>
96	        <button type="button" data-testid="export-people" (click)="exportCsv()">Export people as CSV</button>
97	      </p>
98	
99	      <p>
100	        <button type="button" data-testid="bulk-open" (click)="bulkOpen()" [disabled]="bulkOpening()">Open selected claims</button>
101	        @if (bulkOpenResult(); as r) {
