108	      </p>
109	
110	      <ul data-testid="person-list">
111	        @for (p of listed(); track p.id) {
112	          <li [attr.data-testid]="'person-row-' + p.id">
113	            <span data-testid="person-name">{{ p.name }}</span>
114	            — grade <span data-testid="person-grade">{{ gradeToday(p) }}</span>
115	            — due <span data-testid="person-due-total">{{ dueOf(p) }}</span>
116	            — overdue <span data-testid="person-overdue-count">{{ overdueOf(p.id).count }}</span>
117	            due <span data-testid="person-overdue-total">{{ money(overdueOf(p.id).cents) }}</span>
118	            — statements <span data-testid="person-statement-count">{{ statementOf(p.id)?.count ?? 0 }}</span>
119	            — last stated <span data-testid="person-stated-total">{{ statementOf(p.id)?.dueTotal ?? '' }}</span>
120	            on <span data-testid="person-statement-date">{{ statementOf(p.id)?.date ?? '' }}</span>
121	            — retired <span data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</span>
122	            from <span data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</span>
123	            — on hold <span data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</span>
124	            @if (p.holds.length > 0) {
125	              <ul [attr.aria-label]="'Holds of ' + p.name">
126	                @for (h of p.holds; track $index) {
127	                  <li data-testid="person-hold-line">{{ h.from }} to {{ h.to ?? 'no end' }}</li>
128	                }
129	              </ul>
130	            }
131	            <label [attr.for]="'person-hold-from-' + p.id">Hold from</label>
132	            <input [id]="'person-hold-from-' + p.id" type="date" data-testid="person-hold-from" #holdFrom
133	                   (input)="clearPersonError(p.id)" />
134	            <label [attr.for]="'person-hold-to-' + p.id">to</label>
135	            <input [id]="'person-hold-to-' + p.id" type="date" data-testid="person-hold-to" #holdTo
136	                   (input)="clearPersonError(p.id)" />
137	            <button type="button" data-testid="person-hold-toggle" (click)="hold(p, holdFrom.value, holdTo.value)"
138	                    [disabled]="holding() === p.id" [attr.aria-label]="'Hold ' + p.name">Hold</button>
139	            <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)"
140	                    [attr.aria-label]="'Edit ' + p.name">Edit</button>
141	            <button type="button" data-testid="person-statement" (click)="takeStatement(p)" [disabled]="stating() === p.id"
142	                    [attr.aria-label]="'Take a statement of ' + p.name">Statement</button>
143	            <label [attr.for]="'person-retire-date-' + p.id">Retire from</label>
144	            <input [id]="'person-retire-date-' + p.id" type="date" data-testid="person-retire-date" #retireDate />
145	            <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)" [disabled]="retiring() === p.id"
146	                    [attr.aria-label]="'Retire ' + p.name">Retire</button>
147	            — patrons <span data-testid="person-patrons">{{ patronsOf(p.id) }}</span>
148	            — backing <span data-testid="person-backing">{{ backingOf(p.id) }}</span>
149	            <label [attr.for]="'person-patron-select-' + p.id">Patron</label>
150	            <select [id]="'person-patron-select-' + p.id" data-testid="person-patron-select" #patronSelect
151	                    (change)="patronError.set(null)">
152	              @for (q of people(); track q.id) {
153	                <option [value]="q.id">{{ q.name }}</option>
154	              }
155	            </select>
156	            <button type="button" data-testid="person-patron-add" (click)="addPatron(p, patronSelect.value)"
157	                    [disabled]="addingPatron() === p.id" [attr.aria-label]="'Add a patron of ' + p.name">Add patron</button>
158	            @if (patronError()?.id === p.id) {
159	              <p role="alert" data-testid="person-patron-error">{{ patronError()?.message }}</p>
160	            }
161	            @if (personError()?.id === p.id) {
162	              <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
163	            }
164	            <app-person-claims [personId]="p.id" [personName]="p.name" [claims]="claimsOf(p.id)" [ratesByGrade]="rates.ratesByGrade()" [grades]="p"
165	                               [periods]="periods.list()" [holds]="p.holds" [others]="othersOf(p.id)"
166	                               [selected]="selectedClaims()" (selectToggled)="toggleSelected($event)"
167	                               (saved)="claimSaved($event)" />
168	          </li>
169	        }
170	      </ul>
171	    </section>
172	  `,
173	})
174	export class PeopleList {
175	  private readonly sheets = inject(Sheets);
176	  protected readonly api = inject(People);
177	  private readonly claimsApi = inject(Claims);
178	  private readonly statementsApi = inject(Statements);
179	  private readonly patronsApi = inject(Patrons);
180	  protected readonly rates = inject(Rates);
181	  protected readonly periods = inject(Periods);
182	
183	  protected readonly grades = GRADES;
184	  protected readonly money = money;
185	  protected readonly people = signal<PersonView[]>([]);
186	  /** The people listed: retired people only while "show retired" is on. Totals still count everyone. */
187	  protected readonly listed = computed(() =>
188	    this.api.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
189	  );
190	  /** The person being retired, so a second press waits for the first. */
191	  protected readonly retiring = signal<number | null>(null);
192	  /** The person a hold is being added to, so a second press waits for the first. */
193	  protected readonly holding = signal<number | null>(null);
194	  /** Every claim on the sheet, newest first. */
195	  protected readonly claims = signal<ClaimView[]>([]);
196	  /** The ids of the claims selected for a bulk action. */
197	  protected readonly selectedClaims = signal<ReadonlySet<number>>(new Set());
198	  /** What the last bulk open did, until the button is pressed again. */
199	  protected readonly bulkOpenResult = signal<{ opened: number; refused: number } | null>(null);
200	  protected readonly bulkOpenError = signal<string | null>(null);
201	  /** Whether a bulk open is running, so a second press waits for the first. */
202	  protected readonly bulkOpening = signal(false);
203	  /** Each person's statements, by person; one with none is missing. */
204	  private readonly statements = signal<Map<number, StatementSummary>>(new Map());
205	  /** The person whose statement is being taken, so a second press waits for the first. */
206	  protected readonly stating = signal<number | null>(null);
207	  /** Every patron named on the sheet. */
208	  private readonly patrons = signal<PatronView[]>([]);
209	  /** The person a patron is being added to, so a second press waits for the first. */
210	  protected readonly addingPatron = signal<number | null>(null);
211	  /** The error of the last patron added on a person's row, until the next action on that row. */
212	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
213	  /** Each person's patrons' ids, by person. */
214	  private readonly patronIdsByPerson = computed(() => {
215	    const byPerson = new Map<number, number[]>();
216	    for (const pt of this.patrons()) byPerson.set(pt.personId, [...(byPerson.get(pt.personId) ?? []), pt.patronId]);
217	    return byPerson;
218	  });
219	  /** The error of the last action taken on a person's row, until the next action on that row. */
220	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
221	  private readonly claimsByPerson = computed(() => {
222	    const byPerson = new Map<number, ClaimView[]>();
223	    for (const c of this.claims()) byPerson.set(c.personId, [...(byPerson.get(c.personId) ?? []), c]);
224	    return byPerson;
225	  });
226	  /** For each person, the other people on the sheet their claims can be moved to. */
227	  private readonly othersByPerson = computed(() => {
228	    const people = this.people();
229	    return new Map(people.map((p) => [p.id, people.filter((q) => q.id !== p.id)]));
230	  });
231	  /** Whether each claim counts in the live totals: a person's open claims dated within one of their holds,
232	   *  and not bound by a statement, do not. */
233	  private readonly countsNow = computed(() => {
234	    const byPerson = new Map(this.people().map((p) => [p.id, countsWithHolds(p.holds)]));
235	    return (c: ClaimView) => (byPerson.get(c.personId) ?? countsWithHolds([]))(c);
236	  });
237	  protected readonly claimedTotal = computed(() =>
238	    money(this.claims().filter(this.countsNow()).reduce((sum, c) => sum + cents(c.amount), 0)),
239	  );
240	  /** Each person's due-total in whole cents: the sum of the dues of their claims that count (0 with none);
241	   *  null when neither their grade in force today nor the grade any of those claims is at has a rate in
242	   *  force today, and none of those claims has a due. */
243	  private readonly dueByPerson = computed(() => {
244	    const today = this.rates.byGrade();
245	    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
246	    const byPerson = new Map<number, number | null>();
247	    for (const p of this.people()) {
248	      const counting = this.claimsOf(p.id).filter(countsWithHolds(p.holds));
249	      const grades = [this.gradeToday(p), ...counting.map((c) => gradeOn(p, c.date))];
250	      const dues = counting.map((c) => this.claimDue(p, c, dueTerms)).filter((due) => due !== null);
251	      if (!grades.some((g) => today.has(g)) && dues.length === 0) {
252	        byPerson.set(p.id, null);
253	        continue;
254	      }
255	      byPerson.set(p.id, dues.reduce((sum, due) => sum + due, 0));
256	    }
257	    return byPerson;
258	  });
259	  /** Everyone's due-total added up, skipping those with none. */
260	  protected readonly dueTotal = computed(() =>
261	    money([...this.dueByPerson().values()].reduce<number>((sum, due) => sum + (due ?? 0), 0)),
262	  );
263	  /** Each person's overdue claims that count: how many, and their dues added up in whole cents (none counting as 0). */
264	  private readonly overdueByPerson = computed(() => {
265	    const sheet = this.sheets.current();
266	    const dueTerms = sheet ?? DEFAULT_DUE_TERMS;
267	    const byPerson = new Map<number, Overdue>();
268	    for (const p of this.people()) {
269	      const overdue = sheet
270	        ? this.claimsOf(p.id).filter((c) => countsWithHolds(p.holds)(c) && isOverdue(c, sheet.today))
271	        : NO_CLAIMS;
272	      byPerson.set(p.id, {
273	        count: overdue.length,
274	        cents: overdue.reduce((sum, c) => sum + (this.claimDue(p, c, dueTerms) ?? 0), 0),
275	      });
276	    }
277	    return byPerson;
278	  });
279	  /** Everyone's overdue claims added up. */
280	  protected readonly overdueTotals = computed(() =>
281	    [...this.overdueByPerson().values()].reduce<Overdue>(
282	      (sum, o) => ({ count: sum.count + o.count, cents: sum.cents + o.cents }),
283	      NO_OVERDUE,
284	    ),
285	  );
286	  /** Each period's due-total, by period id: the dues of the claims that count whose date falls in it;
287	   *  a closed period keeps the total fixed when it was closed. */
288	  protected readonly dueByPeriod = computed(() => {
289	    const periods = this.periods.list();
290	    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
291	    const personOf = new Map(this.people().map((p) => [p.id, p]));
292	    const totals = new Map<number, number>(periods.map((p) => [p.id, 0]));
293	    for (const c of this.claims().filter(this.countsNow())) {
294	      const period = periodOn(periods, c.date);
295	      const person = personOf.get(c.personId);
296	      if (!period || !person) continue;
297	      totals.set(period.id, (totals.get(period.id) ?? 0) + (this.claimDue(person, c, dueTerms) ?? 0));
298	    }
299	    const closed = new Map(periods.filter((p) => p.closedTotal !== null).map((p) => [p.id, p.closedTotal as string]));
300	    return new Map([...totals].map(([id, total]) => [id, closed.get(id) ?? money(total)]));
301	  });
302	  /** Per grade: the people not retired on it today and their due-totals added up, skipping those with none. */
303	  protected readonly summaryByGrade = computed<GradeSummary[]>(() => {
304	    const due = this.dueByPerson();
305	    const current = this.people().filter((p) => !p.retired);
306	    return GRADES.map((grade) => {
307	      const onGrade = current.filter((p) => this.gradeToday(p) === grade);
308	      return {
309	        grade,
310	        count: onGrade.length,
311	        dueTotal: money(onGrade.reduce((sum, p) => sum + (due.get(p.id) ?? 0), 0)),
312	      };
313	    });
314	  });
315	  /** Per period: its due-total, as its row shows it. */
316	  protected readonly summaryByPeriod = computed<PeriodSummary[]>(() => {
317	    const due = this.dueByPeriod();
318	    return this.periods.list().map((p) => ({ name: p.name, dueTotal: due.get(p.id) ?? '0.00' }));
319	  });
320	  /** Per status: how many of the sheet's claims are in it. */
321	  protected readonly summaryByStatus = computed<StatusSummary[]>(() => {
322	    const claims = this.claims();
323	    return SUMMARY_STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
324	  });
325	  protected readonly editingId = signal<number | null>(null);
326	  /** The version of the person the editor loaded. */
327	  private editingVersion = 0;
328	  protected readonly error = signal<string | null>(null);
329	  protected readonly saving = signal(false);
330	
331	  protected readonly form = new FormGroup({
332	    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
333	    grade: new FormControl<Grade>('A', { nonNullable: true }),
334	    /** While editing: the date the grade is from (yyyy-mm-dd); blank takes the sheet's today. */
335	    gradeFrom: new FormControl('', { nonNullable: true }),
336	  });
337	
338	  protected readonly quickError = signal<string | null>(null);
339	  protected readonly quickSaving = signal(false);
340	
341	  protected readonly quickForm = new FormGroup({
342	    name: new FormControl('', { nonNullable: true }),
343	    amount: new FormControl('', { nonNullable: true }),
344	  });
345	
346	  constructor() {
347	    // Each (re)load of a sheet re-reads its people from the store.
348	    toObservable(this.sheets.loaded)
349	      .pipe(
350	        switchMap((sheet) => {
351	          this.people.set([]);
352	          this.claims.set([]);
353	          this.selectedClaims.set(new Set());
354	          this.bulkOpenResult.set(null);
355	          this.bulkOpenError.set(null);
356	          this.statements.set(new Map());
357	          this.patrons.set([]);
358	          this.personError.set(null);
359	          this.patronError.set(null);
360	          this.reset();
361	          this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
362	          this.quickError.set(null);
363	          return sheet
364	            ? forkJoin({
365	                people: this.api.list(sheet.id),
366	                claims: this.claimsApi.list(sheet.id),
367	                statements: this.statementsApi.list(sheet.id),
368	                patrons: this.patronsApi.list(sheet.id),
369	              })
370	            : of({ people: [], claims: [], statements: [], patrons: [] });
371	        }),
372	        takeUntilDestroyed(),
373	      )
374	      .subscribe({
375	        next: ({ people, claims, statements, patrons }) => {
376	          this.patrons.set(patrons);
377	          this.people.set(people);
378	          this.claims.set(claims);
379	          this.statements.set(new Map(statements.map((s) => [s.personId, s])));
380	        },
381	      });
382	    // An error is removed as soon as its form is changed.
383	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
384	    this.quickForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.quickError.set(null));
385	  }
386	
387	  protected claimsOf(personId: number): ClaimView[] {
388	    return this.claimsByPerson().get(personId) ?? NO_CLAIMS;
389	  }
390	
391	  /** The person's grade in force on the sheet's today. */
392	  protected gradeToday(p: PersonView): Grade {
393	    return gradeOn(p, this.sheets.current()?.today ?? '');
394	  }
395	
396	  /** A claim's due in whole cents, at the rates of its person's grade in force on its date; null with none. */
397	  private claimDue(p: PersonView, c: ClaimView, dueTerms: DueTerms): number | null {
398	    return claimDueCents(c, this.rates.ratesByGrade().get(gradeOn(p, c.date)) ?? NO_RATES, dueTerms,
399	      roundingDate(c, this.claimsOf(p.id)));
400	  }
401	
402	  protected dueOf(p: PersonView): string {
403	    const due = this.dueByPerson().get(p.id);
404	    return due === null || due === undefined ? NOT_AVAILABLE : money(due);
405	  }
406	
407	  /** Download the people as CSV, in list order, retired people included. */
408	  protected exportCsv(): void {
409	    const lines = [
410	      ['name', 'grade', 'retired-from', 'due-total'],
411	      ...this.people().map((p) => [p.name, this.gradeToday(p), p.retiredFrom ?? '', this.dueOf(p)]),
412	    ].map((fields) => fields.map(csvField).join(',') + '\n');
413	    const url = URL.createObjectURL(new Blob(lines, { type: 'text/csv' }));
414	    const link = document.createElement('a');
415	    link.href = url;
416	    link.download = 'people-' + (this.sheets.current()?.id ?? 'sheet') + '.csv';
417	    link.click();
418	    setTimeout(() => URL.revokeObjectURL(url));
419	  }
420	
421	  /** The person's patrons' names, sorted, comma and space separated. */
422	  protected patronsOf(personId: number): string {
423	    const nameOf = new Map(this.people().map((q) => [q.id, q.name]));
424	    return (this.patronIdsByPerson().get(personId) ?? [])
425	      .map((id) => nameOf.get(id) ?? '')
426	      .sort((a, b) => a.localeCompare(b))
427	      .join(', ');
428	  }
429	
430	  /** The person's backing: their patrons' due-totals added up, skipping those with none; 0.00 with no patrons. */
431	  protected backingOf(personId: number): string {
432	    const due = this.dueByPerson();
433	    return money((this.patronIdsByPerson().get(personId) ?? []).reduce((sum, id) => sum + (due.get(id) ?? 0), 0));
434	  }
435	
436	  /** Name the chosen person as the person's patron; refused when it is themselves or already their patron. */
437	  protected addPatron(p: PersonView, patronId: string): void {
438	    if (this.addingPatron() === p.id) return;
439	    this.personError.set(null);
440	    this.patronError.set(null);
441	    const sheet = this.sheets.current();
442	    if (!sheet || patronId === '') return;
443	    this.addingPatron.set(p.id);
444	    this.patronsApi.add(sheet.id, p.id, Number(patronId)).subscribe({
445	      next: (added) => {
446	        this.addingPatron.set(null);
447	        this.patrons.update((list) => [...list, added]);
448	      },
449	      error: (err: unknown) => {
450	        this.addingPatron.set(null);
451	        this.patronError.set({
452	          id: p.id,
453	          message:
454	            err instanceof HttpErrorResponse && err.status === 422
455	              ? p.name + ' cannot be their own patron.'
456	              : err instanceof HttpErrorResponse && err.status === 409
457	                ? 'That person is already a patron of ' + p.name + '.'
458	                : 'Could not add that patron.',
459	        });
460	      },
461	    });
462	  }
463	
464	  protected overdueOf(personId: number): Overdue {
465	    return this.overdueByPerson().get(personId) ?? NO_OVERDUE;
466	  }
467	
468	  protected statementOf(personId: number): StatementSummary | undefined {
469	    return this.statements().get(personId);
470	  }
471	
472	  /** Take a statement of the person, then show their summary and their claims as it left them. */
473	  protected takeStatement(p: PersonView): void {
474	    if (this.stating() === p.id) return;
475	    this.personError.set(null);
476	    this.patronError.set(null);
477	    const sheet = this.sheets.current();
478	    if (!sheet) return;
479	    this.stating.set(p.id);
480	    this.statementsApi.take(sheet.id, p.id).subscribe({
481	      next: ({ summary, claims }) => {
482	        this.stating.set(null);
483	        this.statements.update((map) => new Map(map).set(summary.personId, summary));
484	        const byId = new Map(claims.map((c) => [c.id, c]));
485	        this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
486	      },
487	      error: () => {
488	        this.stating.set(null);
489	        this.personError.set({ id: p.id, message: 'Could not take a statement of ' + p.name + '.' });
490	      },
491	    });
492	  }
493	
494	  /** Retire the person from a date; a blank date takes the sheet's today. */
495	  protected retire(p: PersonView, from: string): void {
496	    if (this.retiring() === p.id) return;
497	    this.personError.set(null);
498	    this.patronError.set(null);
499	    const sheet = this.sheets.current();
500	    if (!sheet) return;
501	    this.retiring.set(p.id);
502	    this.api.retire(sheet.id, p.id, from === '' ? null : from).subscribe({
503	      next: (retired) => {
504	        this.retiring.set(null);
505	        this.people.update((list) => list.map((q) => (q.id === retired.id ? retired : q)));
506	      },
507	      error: () => {
508	        this.retiring.set(null);
509	        this.personError.set({ id: p.id, message: 'Could not retire ' + p.name + '.' });
510	      },
511	    });
512	  }
513	
514	  /** Put the person on hold over the dates given: a blank from-date takes the sheet's today, a blank to-date has no end. */
515	  protected hold(p: PersonView, from: string, to: string): void {
516	    if (this.holding() === p.id) return;
517	    this.personError.set(null);
518	    this.patronError.set(null);
519	    const sheet = this.sheets.current();
520	    if (!sheet) return;
521	    this.holding.set(p.id);
522	    this.api.hold(sheet.id, p.id, from === '' ? null : from, to === '' ? null : to).subscribe({
523	      next: (saved) => {
524	        this.holding.set(null);
525	        this.people.update((list) => list.map((q) => (q.id === saved.id ? saved : q)));
526	      },
527	      error: () => {
528	        this.holding.set(null);
529	        this.personError.set({ id: p.id, message: 'Could not hold ' + p.name + ' over those dates.' });
530	      },
531	    });
532	  }
533	
534	  /** Clear the error shown on a person's row once its form is changed. */
535	  protected clearPersonError(id: number): void {
536	    if (this.personError()?.id === id) this.personError.set(null);
537	  }
538	
539	  protected toggleSelected({ id, selected }: { id: number; selected: boolean }): void {
540	    this.selectedClaims.update((ids) => {
541	      const next = new Set(ids);
542	      if (selected) next.add(id);
543	      else next.delete(id);
544	      return next;
545	    });
546	  }
547	
548	  /** Open the selected claims together: each that can be is opened, numbered in list order; the rest are left as they are. */
549	  protected bulkOpen(): void {
550	    if (this.bulkOpening()) return;
551	    this.bulkOpenResult.set(null);
552	    this.bulkOpenError.set(null);
553	    const sheet = this.sheets.current();
554	    if (!sheet) return;
555	    this.bulkOpening.set(true);
556	    this.claimsApi.bulkOpen(sheet.id, [...this.selectedClaims()]).subscribe({
557	      next: ({ opened, refused, claims }) => {
558	        this.bulkOpening.set(false);
559	        claims.forEach((c) => this.claimSaved(c));
560	        this.selectedClaims.set(new Set());
561	        this.bulkOpenResult.set({ opened, refused });
562	      },
563	      error: () => {
564	        this.bulkOpening.set(false);
565	        this.bulkOpenError.set('Could not open the selected claims.');
566	      },
567	    });
568	  }
569	
570	  /** A claim as saved: a new one, or one moved to another person, is listed first (its person's newest). */
571	  protected claimSaved(saved: ClaimView): void {
572	    this.claims.update((list) => {
573	      const was = list.find((c) => c.id === saved.id);
574	      return was && was.personId === saved.personId
575	        ? list.map((c) => (c.id === saved.id ? saved : c))
576	        : [saved, ...list.filter((c) => c.id !== saved.id)];
577	    });
578	  }
579	
580	  /** The other people on the sheet a person's claims can be moved to. */
581	  protected othersOf(personId: number): PersonView[] {
582	    return this.othersByPerson().get(personId) ?? [];
583	  }
584	
585	  /** Quick-add a DRAFT claim for the named person, adding them first (grade A) when not on the sheet. */
586	  protected quickAdd(): void {
587	    // A second submit before the first has answered is ignored, so it stores one record.
588	    if (this.quickSaving()) return;
589	    this.quickError.set(null);
590	    const sheet = this.sheets.current();
591	    if (!sheet) return;
592	    const value = this.quickForm.getRawValue();
593	    if (value.name.trim() === '') {
594	      this.quickError.set('Type a name for the person.');
595	      return;
596	    }
597	    const amount = value.amount.trim();
598	    if (!AMOUNT_PATTERN.test(amount)) {
599	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
600	      return;
601	    }
602	    this.quickSaving.set(true);
603	    this.claimsApi.quickAdd(sheet.id, value.name, amount).subscribe({
604	      next: ({ person, personAdded, claim }) => {
605	        this.quickSaving.set(false);
606	        if (personAdded) this.people.update((list) => [...list, person]);
607	        this.claimSaved(claim);
608	        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
609	      },
610	      error: (err: unknown) => {
611	        this.quickSaving.set(false);
612	        this.quickError.set(
613	          err instanceof HttpErrorResponse && err.status === 423
614	            ? 'That claim is dated inside a closed period.'
615	            : err instanceof HttpErrorResponse && err.status === 422
616	              ? 'That claim is dated after the person retired.'
617	            : err instanceof HttpErrorResponse && err.status === 409
618	              ? 'That name is already in use on this sheet.'
619	              : 'Could not add that claim.',
620	        );
621	      },
622	    });
623	  }
624	
625	  protected edit(p: PersonView): void {
626	    this.personError.set(null);
627	    this.patronError.set(null);
628	    this.editingId.set(p.id);
629	    this.editingVersion = p.version;
630	    this.form.setValue({ name: p.name, grade: this.gradeToday(p), gradeFrom: '' }, { emitEvent: false });
631	    this.error.set(null);
632	  }
633	
634	  protected reset(): void {
635	    this.editingId.set(null);
636	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' }, { emitEvent: false });
637	    this.error.set(null);
638	  }
639	
640	  protected submit(): void {
641	    // A second submit before the first has answered is ignored, so it stores one record.
642	    if (this.saving()) return;
643	    this.error.set(null);
644	    const sheet = this.sheets.current();
645	    if (!sheet) return;
646	    const value = this.form.getRawValue();
647	    if (value.name.trim() === '') {
648	      this.error.set('Type a name for the person.');
649	      return;
650	    }
651	    const id = this.editingId();
652	    this.saving.set(true);
653	    const request = id === null
654	      ? this.api.add(sheet.id, { name: value.name, grade: value.grade })
655	      : this.api.update(sheet.id, id, this.editingVersion,
656	          { name: value.name, grade: value.grade, gradeFrom: value.gradeFrom === '' ? null : value.gradeFrom });
657	    request.subscribe({
658	      next: (saved) => {
659	        this.saving.set(false);
660	        this.people.update((list) =>
661	          id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
662	        );
663	        this.reset();
664	      },
665	      error: (err: unknown) => {
666	        this.saving.set(false);
667	        if (id !== null && err instanceof HttpErrorResponse && err.status === 412) {
668	          this.error.set('Someone else has saved this person since you opened it; their values are shown.');
669	          this.showCurrent(sheet.id, id);
670	        } else if (err instanceof HttpErrorResponse && err.status === 409) {
671	          this.error.set('That name is already in use on this sheet.');
672	        } else {
673	          this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
674	        }
675	      },
676	    });
677	  }
678	
679	  /** Re-read the people after a refused edit and show the person's current values in the editor. */
680	  private showCurrent(sheetId: string, id: number): void {
681	    this.api.list(sheetId).subscribe({
682	      next: (people) => {
683	        this.people.set(people);
684	        const current = people.find((p) => p.id === id);
685	        if (current && this.editingId() === id) {
686	          this.editingVersion = current.version;
687	          this.form.setValue({ name: current.name, grade: this.gradeToday(current), gradeFrom: '' }, { emitEvent: false });
688	        }
689	      },
690	    });
691	  }
692	}
